package sohal.lld.zerodha.user;import sohal.lld.zerodha.exception.InsufficientStockException;import java.util.Map;import java.util.concurrent.ConcurrentHashMap;public class Account {    private double balance;    private Map<String,Integer> portfolio;    public Account(double balance) {        this.balance = balance;        this.portfolio = new ConcurrentHashMap<>();    }    public synchronized void debit(double amount) {        if(this.balance < amount) {            throw new RuntimeException("Insufficient balance to debit " + amount);        }        this.balance -= amount;    }    public synchronized void credit(double amount) {        this.balance += amount;    }    public synchronized void addStock(String symbol, int quantity) {        portfolio.put(symbol, portfolio.getOrDefault(symbol, 0) + quantity);    }    public void removeStock(String symbol, int quantity) {        int currentQuantity = portfolio.getOrDefault(symbol, 0);        if(currentQuantity < quantity ) {            throw new InsufficientStockException("Insufficient stock to remove " + symbol);        } else if(currentQuantity == quantity) {            portfolio.remove(symbol);        } else {            portfolio.put(symbol, portfolio.get(symbol) - quantity);        }    }    public double getBalance() {        return balance;    }    public Map<String, Integer> getPortfolio() {        return Map.copyOf(portfolio);    }    public int  getStockQuantity(String stock) {        return portfolio.getOrDefault(stock, 0);    }}